async (page) => {
  const base = 'http://localhost:46387';
  const out = [];
  await page.request.post(base+'/__test/reset');
  await page.goto(base+'/');
  const add = async (name, weight) => {
    await page.goto(base+'/');
    const art = page.getByRole('article', { name });
    if (weight) await art.getByLabel('Weight of '+name).selectOption({label: weight});
    await art.getByRole('button', { name: 'Add' }).click();
  };
  const dump = async (label) => { await page.goto(base+'/basket'); out.push(label+': '+(await page.getByRole('main').innerText()).replace(/\n+/g,' | ') + ' || HDR ' + await page.getByRole('link',{name:/Basket \(/}).innerText()); };
  await add('Bananas, loose','250 g'); await add('Vine tomatoes, loose','750 g'); await add('Carrots, loose','1500 g');
  await dump('produce');
  await page.getByLabel('Voucher code').fill('SAVE10'); await page.getByRole('button',{name:'Apply'}).click();
  out.push('AFTER VOUCHER: '+(await page.getByRole('main').innerText()).replace(/\n+/g,' | '));
  await page.getByRole('button',{name:'Remove one Bananas, loose'}).click();
  out.push('AFTER MINUS: '+(await page.getByRole('main').innerText()).replace(/\n+/g,' | '));
  return out;
}

