async (page) => {
  const base = 'http://localhost:46387';
  const out = [];
  await page.request.post(base+'/__test/reset');
  const line = async () => (await page.getByRole('main').innerText()).replace(/\n+/g,' | ').replace(/Item\s*Quantity\s*Substitutes\s*Price/,'').replace(/Delivery \| No delivery.*?Apply/,'');
  await page.goto(base+'/');
  const nat = page.getByRole('article',{name:'Natural yoghurt 500 g'});
  await nat.getByRole('button',{name:'Add'}).click();
  await page.goto(base+'/basket');
  for (const q of ['2','4','5','6','0']) {
    await page.getByLabel('Quantity of Natural yoghurt 500 g').fill(q);
    await page.getByRole('button',{name:'Update Natural yoghurt 500 g'}).click();
    out.push('qty '+q+': '+await line());
    if (q==='0') break;
  }
  await page.goto(base+'/');
  const b = page.getByRole('article',{name:'Bananas, loose'});
  await b.getByRole('button',{name:'Add'}).click(); // 500g
  await page.goto(base+'/'); await b.getByLabel('Weight of Bananas, loose').selectOption({label:'250 g'}); await b.getByRole('button',{name:'Add'}).click();
  await page.goto(base+'/basket'); out.push('bananas 500+250: '+await line());
  await page.getByRole('button',{name:'Remove one Bananas, loose'}).click(); out.push('minus: '+await line());
  await page.getByRole('button',{name:'Remove one Bananas, loose'}).click(); await page.getByRole('button',{name:'Remove one Bananas, loose'}).click();
  out.push('minus x2 more: '+await line());
  // slot 10:00 3 left -> book thrice via orders
  return out;
}

